// Validate and normalize a website-form submission into a CRM inbound event.
const item = $input.all()[0];
const body = item.json.body || {};
const headers = item.json.headers || {};

// Lightweight abuse protection: optional shared secret plus a honeypot field.
const sharedSecret = $env.FORM_SHARED_SECRET || '';
if (sharedSecret && headers['x-form-secret'] !== sharedSecret) {
  return [{ json: { reject: true, status: 403, message: 'forbidden' } }];
}
if (body.website) {
  // Honeypot filled: acknowledge quietly, never write to the CRM.
  return [{ json: { reject: true, status: 200, message: 'accepted' } }];
}

const submissionId = String(body.submission_id || '').trim();
const name = String(body.name || '').trim();
const email = String(body.email || '').trim();
const phone = String(body.phone || '').trim();
const message = String(body.message || '').trim();
if (!submissionId || !message || (!email && !phone)) {
  return [{ json: { reject: true, status: 422, message: 'submission_id, message and email or phone are required' } }];
}
if (message.length > 10000 || name.length > 200 || email.length > 320 || phone.length > 50) {
  return [{ json: { reject: true, status: 413, message: 'payload too large' } }];
}

const metadata = {};
for (const key of ['form', 'page', 'campaign', 'referrer']) {
  if (body[key]) metadata[key] = String(body[key]).slice(0, 500);
}

return [{
  json: {
    reject: false,
    idempotency_key: 'form:' + submissionId,
    event: {
      channel: 'web_form',
      provider: 'website',
      external_event_id: submissionId,
      event_type: 'form_submission',
      sender_name: name || null,
      sender_email: email || null,
      sender_phone: phone || null,
      subject: body.subject ? String(body.subject).slice(0, 500) : null,
      content: message,
      received_at: body.submitted_at || new Date().toISOString(),
      metadata,
    },
  },
}];
